import pandas as pd,numpy as np
from scipy.optimize import least_squares
files=['train/A_vref_op1.csv','train/A_vref_op3.csv']
D={f:pd.read_csv(f).iloc[::5].reset_index(drop=True) for f in files}
def simq(p,d):
    Kv,Kq,Tq=p
    t=d.time_s.values; V=d.voltage_pu.values; Vs=d.voltage_setpoint_pu.values
    Q0=d.reactive_power_pu.values[0]; V0=V[0]; dt=t[1]-t[0]
    xq=0.0; Qm=np.zeros(len(t))
    for i in range(len(t)):
        Qm[i]=Q0+xq
        xq+=dt*((Kv*(Vs[i]-V0)-Kq*(V[i]-V0)-xq)/Tq)
    return Qm
