import pandas as pd,numpy as np
from scipy.optimize import least_squares
from scipy.signal import lfilter
files=['train/A_vref_op1.csv','train/A_vref_op3.csv','train/A_amb_op1.csv','train/A_amb_op2.csv','train/A_gentrip_op1.csv','train/A_load_op2.csv','train/A_fault_op1.csv','train/A_line_op3.csv']
D={f:pd.read_csv(f) for f in files}
def lp(u,T,dt,x0):
    al=np.exp(-dt/T); return lfilter([1-al],[1,-al],u,zi=[al*x0])[0]
def simQ(p,d):
    A,B,C,Tf=p
    t=d.time_s.values; V=d.voltage_pu.values; Vs=d.voltage_setpoint_pu.values
    dt=t[1]-t[0]; Q0=d.reactive_power_pu.values[0]; V0=V[0]; Vs0=Vs[0]
    xv=lp(V,Tf,dt,V0)
    Q=Q0+A*(Vs-Vs0)+B*(V-V0)+C*(V-xv)/Tf
    return Q
def resid(p,fs):
    return np.concatenate([simQ(p,D[f])-D[f].reactive_power_pu.values for f in fs])
for p0 in [[0.5,2.5,0.0,0.01],[0.5,2.5,0.01,0.05]]:
    res=least_squares(resid,p0,args=(files,),bounds=([-20,-20,-5,0.001],[20,20,5,1.0]))
    print(np.round(res.x,4), np.sqrt(np.mean(res.fun**2)).round(5))
    for f in files:
        d=D[f]; print(' ',f, np.sqrt(np.mean((simQ(res.x,d)-d.reactive_power_pu)**2)).round(5))

